import React, { useState, useEffect } from "react";

const CoverLetterPage = ({ userToken, username }) => {
    const [jobDescription, setJobDescription] = useState("");
    const [coverLetter, setCoverLetter] = useState("");
    const [resumeList, setResumeList] = useState([]);
    const [selectedResume, setSelectedResume] = useState("");

    // ✅ Fetch resumes when page loads
    useEffect(() => {
        const fetchResumeList = async (token) => {
            if (!token) return;

            try {
                const response = await fetch(`/api/resume/list?username=${username}`, {
                    method: 'GET',
                    headers: { Authorization: `Bearer ${token}` },
                });

                const data = await response.json();

                if (response.ok && data.length > 0) {
                    setResumeList(data);
                } else {
                    setResumeList([]);
                }
            } catch (error) {
                console.error("Error fetching resumes:", error);
            }
        };

        fetchResumes();
    }, [username, userToken]);

    // ✅ Fetch selected resume data from MongoDB
    const fetchResumeData = async () => {
        if (!selectedResume) {
            alert("Please select a resume.");
            return;
        }

        try {
            const response = await fetch(`/api/resume?username=${username}&resumeName=${selectedResume}`, {
                method: "GET",
                headers: { Authorization: `Bearer ${userToken}` },
            });

            if (response.ok) {
                const resumeData = await response.json();
                console.log("✅ Retrieved Resume Data:", resumeData);
                generateCoverLetter(resumeData);
            } else {
                console.error("❌ Failed to retrieve resume");
            }
        } catch (error) {
            console.error("❌ Error fetching resume:", error);
        }
    };

    // ✅ Generate cover letter using the selected resume
    const generateCoverLetter = async (resumeData) => {
        if (!jobDescription) {
            alert("Please enter a job description.");
            return;
        }

        console.log("📡 Sending Resume Data:", resumeData);

        try {
            const response = await fetch("/api/generate-cover-letter", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${userToken}`,
                },
                body: JSON.stringify({ resumeData, jobDescription }),
            });

            if (response.ok) {
                const data = await response.json();
                setCoverLetter(data.coverLetter);
            } else {
                alert("Failed to generate cover letter.");
            }
        } catch (error) {
            console.error("❌ Error generating cover letter:", error);
        }
    };

    return (
        <div style={{ padding: "20px" }}>
            <h1>Generate Cover Letter</h1>

            {/* Resume Selection */}
            <label>Select a resume:</label>
            <select value={selectedResume} onChange={(e) => setSelectedResume(e.target.value)}>
                <option value="">-- Choose a Resume --</option>
                {resumeList.map((resume) => (
                    <option key={resume._id} value={resume.resumeName}>
                        {resume.resumeName}
                    </option>
                ))}
            </select>

            <button onClick={fetchResumeData} style={{ marginLeft: "10px" }}>
                Use This Resume
            </button>

            {/* Job Description Input */}
            <textarea
                placeholder="Enter job description"
                value={jobDescription}
                onChange={(e) => setJobDescription(e.target.value)}
                rows="5"
                style={{ width: "100%", marginTop: "10px" }}
            ></textarea>

            <button onClick={() => fetchResumeData()} style={{ marginTop: "10px" }}>
                Generate Cover Letter
            </button>

            {/* Display Generated Cover Letter */}
            {coverLetter && (
                <div style={{ marginTop: "20px", padding: "10px", border: "1px solid #ddd" }}>
                    <h2>Your Cover Letter:</h2>
                    <p>{coverLetter}</p>
                </div>
            )}
        </div>
    );
};

export default CoverLetterPage;
